    Checks whether the given number is prime or not.
    """
    def is_prime(self, n: int) -> bool:
        # Numbers less than or equal to 1 are not prime.
        if n <= 1:
            return False

        # 2 is the smallest prime number.
        if n == 2:
            return True

        # Any even number greater than 2 is not prime.
        if n % 2 == 0:
